//go:build !windows

package terminal

import (
	"strings"
	"sync"
	"testing"
	"time"

	"mincode/app/backend/core"
)

// Exercise the same backend command and event route used by LocalTerminal.vue.
// The markers are generated by the test; no user input or shell contents are logged.
func TestLocalShellRapidInputReachesEventAndCommand(t *testing.T) {
	const sessionID = "local-rapid-input-test"
	shell := "/bin/sh"
	// Simulate an independently opened stream for this session: it must not
	// suppress the frontend event consumed by LocalTerminal.vue.
	conn := newFakeStreamConn()
	stream := &wireStreamSession{conns: map[core.StreamConn]struct{}{conn: {}}}
	stream.active.Store(true)
	streamHub.mu.Lock()
	streamHub.sessions[sessionID] = stream
	streamHub.mu.Unlock()
	t.Cleanup(func() {
		streamHub.mu.Lock()
		delete(streamHub.sessions, sessionID)
		streamHub.mu.Unlock()
		_ = conn.Close()
	})
	var mu sync.Mutex
	var output strings.Builder
	updates := make(chan struct{}, 1)
	core.SetEmitter(func(name string, data any) {
		if name != shellOutputEventName(sessionID) {
			return
		}
		payload, ok := data.(shellOutputPayload)
		if !ok || payload.SessionID != sessionID {
			return
		}
		mu.Lock()
		output.WriteString(payload.Data)
		mu.Unlock()
		select {
		case updates <- struct{}{}:
		default:
		}
	})
	t.Cleanup(func() { core.SetEmitter(nil) })

	if _, err := startLocalShell(StartLocalShellPayload{SessionID: sessionID, CustomPath: &shell, InitialArgs: []string{"-i"}}); err != nil {
		t.Skipf("local PTY unavailable: %v", err)
	}
	t.Cleanup(func() {
		if proc, ok := sessions.remove(sessionID); ok {
			shutdownShellProcess(proc)
		}
	})

	const digits = "123456789012345678901234567890"
	for _, digit := range "printf 'BEGIN%sEND\\n' " + digits + "\r" {
		if err := writeToShell(WriteToShellPayload{SessionID: sessionID, Input: string(digit)}); err != nil {
			t.Fatalf("PTY input failed: %v", err)
		}
	}

	wantResult := "BEGIN" + digits + "END"
	deadline := time.NewTimer(10 * time.Second)
	defer deadline.Stop()
	for {
		mu.Lock()
		got := output.String()
		mu.Unlock()
		if strings.Contains(got, wantResult) {
			return
		}
		select {
		case <-updates:
		case <-deadline.C:
			t.Fatalf("command result not delivered by shell-output (received %d bytes)", len(got))
		}
	}
}

// The output owner's existing onExit signal runs after read EOF, final flush,
// session retirement and PTY close. Never make shutdownShellProcess self-join:
// the same output owner invokes it during retirement.
func TestLocalShellCloseCompletesOutputOwner(t *testing.T) {
	const id = "local-close-output-owner-test"
	shell := "/bin/sh"
	home := t.TempDir()
	payload := StartLocalShellPayload{SessionID: id, CustomPath: &shell, Cwd: &home, InitialArgs: []string{"-i"},
		ExtraEnv: map[string]string{"HOME": home, "HISTFILE": "/dev/null", "ENV": "", "BASH_ENV": ""}}
	observed := make(chan struct{}, 1)
	core.SetEmitter(func(name string, value any) {
		if name != shellOutputEventName(id) {
			return
		}
		output, ok := value.(shellOutputPayload)
		if ok && strings.Contains(output.Data, "OWNER-READY") {
			select {
			case observed <- struct{}{}:
			default:
			}
		}
	})
	t.Cleanup(func() { core.SetEmitter(nil) })
	exited := make(chan struct{})
	var childWaited <-chan struct{}
	_, err := runLocalShellSession(id, false, nil, nil, "test_close_output_owner", func(cols, rows uint16) (localPTYHandle, string, error) {
		handle, fallback, err := startLocalPTY(payload, cols, rows)
		if native, ok := handle.(*unixPTY); ok {
			childWaited = native.waited
		}
		return handle, fallback, err
	}, func() { close(exited) }, nil)
	if err != nil {
		t.Fatal(err)
	}
	closeAndJoin := func() {
		if proc, ok := sessions.remove(id); ok {
			shutdownShellProcess(proc)
		}
		select {
		case <-exited:
		case <-time.After(time.Second):
			t.Error("output owner did not finish after PTY close")
		}
		if childWaited == nil {
			t.Error("real Unix PTY child wait owner missing")
			return
		}
		select {
		case <-childWaited:
		case <-time.After(time.Second):
			t.Error("owned PTY child was not reaped")
		}
	}
	t.Cleanup(closeAndJoin)
	if err := writeToShell(WriteToShellPayload{SessionID: id, Input: "printf 'OWNER-READY\\n'\r"}); err != nil {
		t.Fatal(err)
	}
	select {
	case <-observed:
	case <-time.After(time.Second):
		t.Fatal("real output pump did not deliver readiness marker")
	}
	closeAndJoin()
	if _, exists := sessions.get(id); exists {
		t.Error("closed output owner still registered")
	}
}
